  /** Hair, or the wrap fabric. */
  hair: string;
  /** Hair shade, darker than hair. */
  hairShade: string;
  /** Tunic body. */
  outfit: string;
  /** Tunic shade, on the right of the body. */
  outfitShade: string;
  /** Tunic highlight: the left column and the near sleeve. */
